public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || !(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        if (actualTypeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArgument;
            Type[] bounds = typeVariable.getBounds();
            if (bounds.length == 0) {
                // default to 'Object'
                resolvedArguments[i] = Object.class;
            } else {
                resolvedArguments[i] = resolveType(bounds[0], targetType);
            }
        } else if (actualTypeArgument instanceof WildcardType) {
            resolvedArguments[i] = resolveType(((WildcardType) actualTypeArgument).getUpperBounds()[0], targetType);
        } else {
            resolvedArguments[i] = resolveType(actualTypeArgument, targetType);
        }
    }

    return resolvedArguments;
}

private static Class<?> resolveType(Type type,Class<?> targetType) {
    if (type instanceof Class) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return resolveParameterizedType((ParameterizedType) type, targetType);
    }
    if (type instanceof TypeVariable) {
        return resolveTypeVariable((TypeVariable<?>) type, targetType);
    }
    if (type instanceof GenericArrayType) {
        return resolveGenericArrayType((GenericArrayType) type, targetType);
    }
    if (type instanceof WildcardType) {
        return resolveWildcardType((WildcardType) type, targetType);
    }
    throw new IllegalArgumentException("Unsupported type: " + type);
}

private static Class<?> resolveParameterizedType(ParameterizedType parameterizedType, Class<?> targetType) {
    Class<?> rawType = (Class<?>) parameterizedType.getRawType();
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
        resolvedArguments[i] = resolveType(actualTypeArguments[i], targetType);
    }

    return rawType.getDeclaredClasses()[0];
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    return targetType;
}

private static Class<?> resolveGenericArrayType(GenericArrayType genericArrayType, Class<?> targetType) {
    Type genericComponentType = genericArrayType.getGenericComponentType();
    Class<?> componentClass = resolveType(genericComponentType, targetType);
    return Array.newInstance(componentClass, 0).getClass();
}

private static Class<?> resolveWildcardType(WildcardType wildcardType, Class<?> targetType) {
    Type[] upperBounds = wildcardType.getUpperBounds();
    Type[] lowerBounds = wildcardType.getLowerBounds();
    if (upperBounds.length == 0) {
        // default to 'Object'
        return Object.class;
    }
    if (upperBounds.length == 1) {
        return resolveType(upperBounds[0], targetType);
    }
    if (lowerBounds.length == 1 && lowerBounds[0].equals(Object.class)) {
        return resolveType(upperBounds[0], targetType);
    }
    throw new IllegalArgumentException("WildcardType with multiple upper or lower bounds encountered.");
}

