static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the year, month, and day from the time bucket
    int year = (int) (timeBucket / 1000000000000L);
    int month = (int) ((timeBucket - year * 1000000000000L) / 100000000L);
    int day = (int) (timeBucket - year * 1000000000000L - month * 100000000L);

    // Calculate the new year and month based on the day step
    year += dayStep / 12;
    month += dayStep % 12;

    // Adjust the month and day if necessary
    if (month > 12) {
        year++;
        month -= 12;
    }
    if (day > 30) {
        month++;
        day -= 30;
    }

    return year * 1000000000000L + month * 100000000L + day;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;

    while (index < len) {
        final char c = str.charAt(index++);

        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            final char low = str.charAt(index++);
            if (Character.isLowSurrogate(low) && Character.isSupplementaryCodePoint(c * 0x400 + low)) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Illegal surrogate: " + c + low);
            }
        } else {
            size += 3;
        }
    }

    return size;
